mapper.select:
select
a.inspection_id,
a.inspection_code,
a.robot_id,
a.inspection_name,
a.inspection_type,
a.component_id,
a.meter_type,
a.appearance_type,
a.main_operation_type,
a.operation_type,
a.save_type_list,
a.recognition_type_list,
a.phase,
a.device_info,
property_pic_path
from t_robot_inspection a
where 1 = 1
 and a.inspection_id = #{inspectionId, jdbcType=BIGINT}
 and a.inspection_code = #{inspectionCode, jdbcType=VARCHAR}
 and a.robot_id = #{robotId, jdbcType=BIGINT}
 and a.inspection_name = #{inspectionName, jdbcType=VARCHAR}
 and a.inspection_type = #{inspectionType, jdbcType=INTEGER}
and a.component_id = #{componentId, jdbcType=VARCHAR}
and a.meter_type = #{meterType, jdbcType=Integer}
and a.appearance_type = #{appearanceType, jdbcType=Integer}
and a.main_operation_type = #{mainOperationType, jdbcType=Integer}
and a.operation_type = #{operationType, jdbcType=Integer}
and a.save_type_list = #{saveTypeList, jdbcType=VARCHAR}
a.recognition_type_list = #{recognitionTypeList, jdbcType=VARCHAR}
and a.phase = #{phase, jdbcType=VARCHAR}
and a.device_info = #{deviceInfo, jdbcType=VARCHAR}
and a.property_pic_path = #{propertyPicPath, jdbcType=VARCHAR}

select
a.inspection_id,
a.inspection_code,
a.robot_id,
a.inspection_name,
a.inspection_type,
a.alarm_top,
a.alarm_bottom,
a.default_value,
a.inspection_position,
a.collect_status,
a.calibration_status,
a.unit
from t_robot_inspection a
where 1 = 1
 and a.inspection_id = #{inspectionId, jdbcType=BIGINT}
 and a.inspection_code = #{inspectionCode, jdbcType=VARCHAR}
 and a.robot_id = #{robotId, jdbcType=BIGINT}
 and a.inspection_name = #{inspectionName, jdbcType=VARCHAR}
 and a.inspection_type = #{inspectionType, jdbcType=INTEGER}
 and a.alarm_top = #{alarmTop, jdbcType=VARCHAR}
 and a.alarm_bottom = #{alarmBottom, jdbcType=VARCHAR}
 and a.default_value = #{defaultValue, jdbcType=VARCHAR}
 and a.inspection_position = #{inspectionPosition, jdbcType=INTEGER}
 and a.collect_status = #{collectStatus, jdbcType=INTEGER}
 and a.calibration_status = #{calibrationStatus, jdbcType=INTEGER}
 and a.unit = #{unit, jdbcType=VARCHAR}

